  const id = `hero-${player.id}-${state.heroes.length}-${state.day}`;
  const hero: Hero = {
    id,
    owner: player.id,
    name: `Capitán de ${town.name}`,
    faction: town.faction,
    attack: 1,
    defense: 1,
    spellPower: 1,
