export function bestTargetByLookahead(
  state: GameState,
  viewer: LeaderId,
  baseline: Order[],
  candidates: readonly LeaderId[],
  launch: LookaheadLaunchSpec,
  opponentPlanner: (state: GameState, leaderId: LeaderId) => Order[],
): LeaderId | null {
  if (candidates.length === 0) return null;

  let best: LeaderId | null = null;
  let bestScore = -Infinity;

  for (const target of candidates) {
    const selfOrders: Order[] = [
      ...baseline,
      { kind: 'launch', target, ...launch },
    ];
    const ordersByLeader: Partial<Record<LeaderId, Order[]>> = {
      [viewer]: selfOrders,
    };
    for (const id of state.cast) {
      if (id === viewer) continue;
      const opp = state.leaders[id];
      if (!opp || !opp.alive) continue;
      if (isHuman(id)) {
        // Project the human by their most recent non-empty round within a
        // sliding window (Approach B — see recentHumanOrders). A recent pass no
        // longer reads as passivity. simulateOneRound re-validates and drops
        // orders the human can no longer afford (e.g. a launch from an earlier
        // round when their stockpile is now empty).
        ordersByLeader[id] = recentHumanOrders(state.orderHistory, id);
        continue;
      }
      ordersByLeader[id] = opponentPlanner(state, id);
    }
    const projected = simulateOneRound(state, ordersByLeader);
    const score = scoreState(projected, viewer);
    if (score > bestScore) {
      bestScore = score;
      best = target;
    }
  }

  return best;
}

