export function turtle(state: GameState, id: LeaderId = 'player1'): Order[] {
  const me = state.leaders[id];
  if (!me || !me.alive) return [];
  const orders: Order[] = [];
  const tryAdd = adder(state, id, me.ap, orders);
  const others = aliveOthers(state, id);
  const threatened = others.some((t) => (me.grudge[t] ?? 0) > 0);

  if (state.round <= 3) tryAdd({ kind: 'build-factory' });
  tryAdd({ kind: 'build-defence', type: 'shield' });
  if (me.stockpile.shields >= 1 || threatened) tryAdd({ kind: 'deploy-defence', type: 'shield' });
  tryAdd({ kind: 'build-defence', type: 'aa' });
  if (me.stockpile.aa >= 1) tryAdd({ kind: 'deploy-defence', type: 'aa' });
  return orders;
}

export function applyWooing(
  state: GameState,
  ordersByLeader: Partial<Record<LeaderId, Order[]>>,
): WooingResult {
  const next: GameState = structuredClone(state);
  const events: ResolutionEvent[] = [];
  const senders = Object.keys(ordersByLeader).sort() as LeaderId[];
  for (const id of senders) {
    const orders = ordersByLeader[id] ?? [];
    for (const o of orders) {
      if (o.kind !== 'woo') continue;
      const me = next.leaders[id];
      const target = next.leaders[o.target];
      if (!me || !me.alive || !target || !target.alive) continue;
      const current = target.favourability[id] ?? 0;
      const points = ACTION_COSTS.woo;
      target.favourability[id] = current + points;
      events.push({ kind: 'WooApplied', from: id, to: o.target, points });
    }
  }
  return { state: next, events };
}

