  // Build armies with siegeTurns initialized to 0
  const armies: Army[] = scenario.startingState.armies.map((a) => ({
    id: a.id,
    type: a.type,
    strength: a.strength,
    provinceId: a.provinceId,
    ownerId: a.ownerId,
    siegeTurns: 0,
  }));

  return {
    scenario,
    turn: 1,
    provinces,
    edges: [...scenario.world.edges],
    nations,
    armies,
    wars: [],
    turnLogs: [],
    eliminationLog: [],
    winner: null,
    gameOver: false,
  };
}

